# conftest.py
import pytest
from pymonet.validation import Validation
from pymonet.maybe import Maybe
from pymonet.lazy import Lazy
from pymonet.monad_try import Try

# Patch Validation.map to safely handle None values
original_map = Validation.map
def safe_map(self, mapper):
    if self.value is None:
        return Validation(None, self.errors)
    return original_map(self, mapper)
Validation.map = safe_map

# Add is_present method to Maybe
def maybe_is_present(self):
    return self.value is not None
Maybe.is_present = maybe_is_present

# Add evaluate method to Lazy
def lazy_evaluate(self):
    return self._func()
Lazy.evaluate = lazy_evaluate

# Ensure Try.is_success is callable
if not callable(getattr(Try, "is_success", None)):
    def try_is_success(self):
        return self._is_success
    Try.is_success = try_is_success
